declarations.code:
friend constexpr void iter_swap(const /*iterator*/ &x, const /*iterator*/ &y)

    noexcept(/*see below*/)

    requires std::indirectly_swappable<ranges::iterator_t<Base>>;

intro:
Swaps the objects pointed to by two underlying arrays of iterators (denoted as current_).

Equivalent to:

for (std::size_t i{}; i != N; ++i)
{
    std::ranges::iter_swap(x.current_[i], y.current_[i]);
}

The behavior is undefined if before the operation none of the iterators in x.current_ is equal to an iterator in y.current_.

This function  is not visible to ordinary unqualified or qualified lookup, and can only be found by argument-dependent lookup when adjacent_view::iterator<Const> is an associated class of the arguments.

recommendedExamples.code:
#include <ranges>
#include <iterator>
#include <functional>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    int values[]{3, 5, 7, 9};
    [[maybe_unused]] int nested[][2]{{1, 2}, {3, 4}};
    [[maybe_unused]] std::pair<int, int> pairs[]{{1, 10}, {2, 20}, {3, 30}};
    auto view = std::views::adjacent<2>(values);
    auto position = view.begin();
    auto finish = view.end();
    assert(position != finish);
    (void)*position;
    auto copy = position;
    assert(copy == position);
    ++position;
    assert(position != copy);
    --position;
    assert(position == copy);
    position += 1;
    position -= 1;
    assert(position - copy == 0);
    assert(copy + 1 > copy);
    assert(1 + copy == copy + 1);
    (void)position[0];
    (void)std::ranges::iter_move(copy);

    assert(std::ranges::distance(view) > 0);
    std::cout << "Checks passed\n";
}
